function runSkillModal(skillId?: string): void {
  const skills = app.snapshot.skills; if (!skills.length) { installSkillModal(); return; } const chosen = skillId ?? skills[0]!.id;
  const skillOptions = skills.map((item): [string, string] => [item.id, `${item.manifest.name} · ${item.id}`]); const changeOptions = app.snapshot.changes.map((item): [string, string] => [item.id, `${item.id} · ${item.title}`]);
  modal({ title: "运行 Skill", description: "输入将按 Skill 协议执行；平台操作仍经过 ToolBroker 权限检查。", wide: true, fields: field("Skill", "skillId", { type: "select", full: true, options: skillOptions }) + field("关联变更", "changeId", { type: "select", options: [["", "不关联"], ...changeOptions] }) + `<div class="field"><label class="checkbox"><input type="checkbox" name="approved" value="true"> 已获得本次写操作/高风险执行审批</label></div>` + field("JSON 输入", "input", { type: "textarea", code: true, full: true, required: true, value: '{\n  "requirement": "支持批量取消；保留审计日志"\n}' }), submit: "运行 Skill", onSubmit: async (data) => { const values = formValues(data); let input: unknown; try { input = JSON.parse(values.input ?? ""); } catch { throw new Error("JSON 输入格式无效"); } await request(`/api/skills/${encodeURIComponent(values.skillId ?? "")}/runs`, { method: "POST", body: JSON.stringify({ input, changeId: values.changeId || undefined, approved: values.approved === "true" }) }); app.view = "runs"; toast("Skill 运行完成"); } });
  setTimeout(() => { $<HTMLSelectElement>('[name="skillId"]').value = chosen; const change = selectedChange(); if (change) $<HTMLSelectElement>('[name="changeId"]').value = change.id; }, 0);
}
