$$<HTMLElement>(".nav-item").forEach((item) => item.addEventListener("click", () => { const view = item.dataset.view; if (view === "changes" || view === "board" || view === "devops" || view === "skills" || view === "runs") { app.view = view; render(); if(view==="devops"&&!app.devops&&!app.devopsLoading)void loadDevOps(); } })); $("#primary-action").addEventListener("click", () => app.view === "changes" ? createChangeModal() : app.view === "board" ? newTaskModal() : app.view === "devops" ? triggerPipelineModal() : app.view === "skills" ? installSkillModal() : runWorkflowModal()); $("#install-skill").addEventListener("click", installSkillModal);
$("#change-list").addEventListener("click", (event) => { const row = event.target instanceof Element ? rowWithData(event.target, "[data-change-id]") : null; const id = row?.dataset.changeId; if (id) { app.selectedChange = id; app.view = "changes"; localStorage.setItem("cjhx:selected-change", id); render(); } });
$("#content").addEventListener("change", (event) => { const select = event.target instanceof HTMLSelectElement ? event.target : null; const filter = select?.dataset.boardFilter; if (select && (filter === "changeId" || filter === "owner" || filter === "risk" || filter === "status")) { app.boardFilters[filter] = select.value; renderBoard(); } else if(select?.dataset.devopsFilter==="changeId"){app.devopsChangeId=select.value;app.devops=null;void loadDevOps()} });
$("#content").addEventListener("click", (event) => { const target = event.target instanceof Element ? rowWithData(event.target, "button,[data-run-id],[data-task-id]") : null; if (!target) return; const tab = target.dataset.tab; if (tab === "evidence" || tab === "tasks" || tab === "history" || tab === "runs") { app.evidenceTab = tab; renderChange(); } else if (target.dataset.taskId) taskDetailModal(target.dataset.taskId); else if (target.dataset.transition && lifecycle.includes(target.dataset.transition as LifecycleState)) transitionModal(target.dataset.transition as LifecycleState); else if (target.dataset.runSkill) runSkillModal(target.dataset.runSkill); else if (target.dataset.runId) showRun(target.dataset.runId); else if(target.dataset.pipelineId)triggerPipelineModal(target.dataset.pipelineId,target.dataset.pipelineKind==="cd"?"cd":"ci");else if(target.dataset.serviceId&&(target.dataset.serviceAction==="start"||target.dataset.serviceAction==="stop"||target.dataset.serviceAction==="restart"))serviceControlModal(target.dataset.serviceId,target.dataset.serviceAction);else { const actions: Record<string, () => void> = { "new-change": createChangeModal, "new-task": newTaskModal, "import-tasks": importTasksModal, "add-evidence": addEvidenceModal, "install-skill": installSkillModal, "run-skill": () => runSkillModal(), "run-workflow": runWorkflowModal, "refresh-devops":()=>{void loadDevOps()}, "trigger-pipeline":()=>triggerPipelineModal() }; const action = target.dataset.action; if (action) actions[action]?.(); } });
$("#content").addEventListener("keydown", (event) => { if (event.key !== "Enter" && event.key !== " ") return; const target = event.target instanceof Element ? rowWithData(event.target, "[data-task-id]") : null; if (target?.dataset.taskId) { event.preventDefault(); taskDetailModal(target.dataset.taskId); } });
function rowWithData(target: Element, selector: string): HTMLElement | null { const row = target.closest(selector); return row instanceof HTMLElement ? row : null; }
document.addEventListener("keydown", (event) => { const mod = navigator.userAgent.includes("Mac") ? event.metaKey : event.ctrlKey; if (mod && event.key.toLowerCase() === "k") { event.preventDefault(); $<HTMLInputElement>("#change-search").focus(); } if (event.key === "Escape" && $("#modal-root").children.length) $("#modal-root").innerHTML = ""; }); $("#search-key").textContent = navigator.userAgent.includes("Mac") ? "⌘K" : "Ctrl+K";
